using Myriale.Api.Architecture;
namespace Myriale.Api.Features.NarrativeGeneration;
[FeatureSlice("NarrativeGeneration")] public static class NarrativeGenerationFeature { public static IServiceCollection AddNarrativeGenerationFeature(this IServiceCollection s,IConfiguration c){s.AddScoped<MockAiNarrativeGenerator>();s.AddScoped<ProviderNarrativeGenerator>();s.AddScoped<INarrativeGenerator>(p=>UseMock(c)?p.GetRequiredService<MockAiNarrativeGenerator>():p.GetRequiredService<ProviderNarrativeGenerator>());s.AddScoped<IScenarioTurnAiService>(p=>UseMock(c)?p.GetRequiredService<MockAiNarrativeGenerator>():p.GetRequiredService<ProviderNarrativeGenerator>());s.AddScoped<IActionRecommendationGenerator>(p=>UseMock(c)?p.GetRequiredService<MockAiNarrativeGenerator>():p.GetRequiredService<ProviderNarrativeGenerator>());s.AddOptions<NarrativeContextOptions>().Bind(c.GetSection(NarrativeContextOptions.SectionName)).Validate(o=>o.RecentTurnsTokenBudget>=0,"Narrative recent-turn budget must be non-negative.").ValidateOnStart();s.AddSingleton<INarrativeRecentTurnSelector,NarrativeRecentTurnSelector>();s.AddSingleton<INarrativeTokenEstimator,Utf8NarrativeTokenEstimator>();return s;} private static bool UseMock(IConfiguration c)=>string.Equals(c["AiRuntime:Mode"],"mock",StringComparison.OrdinalIgnoreCase); public static IEndpointRouteBuilder MapNarrativeGenerationFeature(this IEndpointRouteBuilder e)=>e;}
